            vfloat32m1_t x2  = __riscv_vle32_v_f32m1(&apps_x2[i], vl);
            vfloat32m1_t x3  = __riscv_vle32_v_f32m1(&apps_x3[i], vl);
            vfloat32m1_t x4  = __riscv_vle32_v_f32m1(&apps_x4[i], vl);

            vfloat32m1_t y1  = __riscv_vle32_v_f32m1(&apps_y1[i], vl);
            vfloat32m1_t y2  = __riscv_vle32_v_f32m1(&apps_y2[i], vl);
            vfloat32m1_t y3  = __riscv_vle32_v_f32m1(&apps_y3[i], vl);
            vfloat32m1_t y4  = __riscv_vle32_v_f32m1(&apps_y4[i], vl);

            vfloat32m1_t fx1 = __riscv_vle32_v_f32m1(&apps_fx1[i], vl);
            vfloat32m1_t fx2 = __riscv_vle32_v_f32m1(&apps_fx2[i], vl);
            vfloat32m1_t fx3 = __riscv_vle32_v_f32m1(&apps_fx3[i], vl);
            vfloat32m1_t fx4 = __riscv_vle32_v_f32m1(&apps_fx4[i], vl);

            vfloat32m1_t fy1 = __riscv_vle32_v_f32m1(&apps_fy1[i], vl);
            vfloat32m1_t fy2 = __riscv_vle32_v_f32m1(&apps_fy2[i], vl);
            vfloat32m1_t fy3 = __riscv_vle32_v_f32m1(&apps_fy3[i], vl);
            vfloat32m1_t fy4 = __riscv_vle32_v_f32m1(&apps_fy4[i], vl);

            vfloat32m1_t xi = __riscv_vfmul_vf_f32m1(
                __riscv_vfsub_vv_f32m1(
                    __riscv_vfsub_vv_f32m1(
                        __riscv_vfadd_vv_f32m1(x1, x2, vl),
                        x3, vl),
                    x4, vl),
                half, vl);

            vfloat32m1_t xj = __riscv_vfmul_vf_f32m1(
                __riscv_vfsub_vv_f32m1(
                    __riscv_vfsub_vv_f32m1(
                        __riscv_vfadd_vv_f32m1(x2, x3, vl),
                        x4, vl),
                    x1, vl),
                half, vl);

            vfloat32m1_t yi = __riscv_vfmul_vf_f32m1(
                __riscv_vfsub_vv_f32m1(
                    __riscv_vfsub_vv_f32m1(
                        __riscv_vfadd_vv_f32m1(y1, y2, vl),
                        y3, vl),
                    y4, vl),
                half, vl);

            vfloat32m1_t yj = __riscv_vfmul_vf_f32m1(
                __riscv_vfsub_vv_f32m1(
                    __riscv_vfsub_vv_f32m1(
                        __riscv_vfadd_vv_f32m1(y2, y3, vl),
                        y4, vl),
                    y1, vl),
                half, vl);

            vfloat32m1_t fxi = __riscv_vfmul_vf_f32m1(
                __riscv_vfsub_vv_f32m1(
                    __riscv_vfsub_vv_f32m1(
                        __riscv_vfadd_vv_f32m1(fx1, fx2, vl),
                        fx3, vl),
                    fx4, vl),
                half, vl);

            vfloat32m1_t fxj = __riscv_vfmul_vf_f32m1(
                __riscv_vfsub_vv_f32m1(
                    __riscv_vfsub_vv_f32m1(
                        __riscv_vfadd_vv_f32m1(fx2, fx3, vl),
                        fx4, vl),
                    fx1, vl),
                half, vl);

            vfloat32m1_t fyi = __riscv_vfmul_vf_f32m1(
                __riscv_vfsub_vv_f32m1(
                    __riscv_vfsub_vv_f32m1(
                        __riscv_vfadd_vv_f32m1(fy1, fy2, vl),
                        fy3, vl),
                    fy4, vl),
                half, vl);

            vfloat32m1_t fyj = __riscv_vfmul_vf_f32m1(
                __riscv_vfsub_vv_f32m1(
                    __riscv_vfsub_vv_f32m1(
                        __riscv_vfadd_vv_f32m1(fy2, fy3, vl),
                        fy4, vl),
                    fy1, vl),
                half, vl);

            vfloat32m1_t denom = __riscv_vfadd_vf_f32m1(
                __riscv_vfsub_vv_f32m1(
                    __riscv_vfmul_vv_f32m1(xi, yj, vl),
                    __riscv_vfmul_vv_f32m1(xj, yi, vl),
                    vl),
                ptiny, vl);

            vfloat32m1_t rarea = __riscv_vfrdiv_vf_f32m1(denom, 1.0f, vl);

            vfloat32m1_t dfxdx = __riscv_vfmul_vv_f32m1(
                rarea,
                __riscv_vfsub_vv_f32m1(
                    __riscv_vfmul_vv_f32m1(fxi, yj, vl),
                    __riscv_vfmul_vv_f32m1(fxj, yi, vl),
                    vl),
                vl);

            vfloat32m1_t dfydy = __riscv_vfmul_vv_f32m1(
                rarea,
                __riscv_vfsub_vv_f32m1(
                    __riscv_vfmul_vv_f32m1(fyj, xi, vl),
                    __riscv_vfmul_vv_f32m1(fyi, xj, vl),
                    vl),
                vl);

            vfloat32m1_t affine = __riscv_vfdiv_vv_f32m1(
                __riscv_vfadd_vv_f32m1(
                    __riscv_vfadd_vv_f32m1(fy1, fy2, vl),
                    __riscv_vfadd_vv_f32m1(fy3, fy4, vl),
                    vl),
                __riscv_vfadd_vv_f32m1(
                    __riscv_vfadd_vv_f32m1(y1, y2, vl),
                    __riscv_vfadd_vv_f32m1(y3, y4, vl),
                    vl),
                vl);

            vfloat32m1_t divv = __riscv_vfadd_vv_f32m1(
                __riscv_vfadd_vv_f32m1(dfxdx, dfydy, vl),
                affine, vl);

            __riscv_vse32_v_f32m1(&apps_div[i], divv, vl);
            i += (Index_type)vl;
        }
#else
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            real_t xi  = half * ( apps_x1[i]  + apps_x2[i]  - apps_x3[i]  - apps_x4[i]  );
            real_t xj  = half * ( apps_x2[i]  + apps_x3[i]  - apps_x4[i]  - apps_x1[i]  );
            real_t yi  = half * ( apps_y1[i]  + apps_y2[i]  - apps_y3[i]  - apps_y4[i]  );
            real_t yj  = half * ( apps_y2[i]  + apps_y3[i]  - apps_y4[i]  - apps_y1[i]  );
            real_t fxi = half * ( apps_fx1[i] + apps_fx2[i] - apps_fx3[i] - apps_fx4[i] );
            real_t fxj = half * ( apps_fx2[i] + apps_fx3[i] - apps_fx4[i] - apps_fx1[i] );
            real_t fyi = half * ( apps_fy1[i] + apps_fy2[i] - apps_fy3[i] - apps_fy4[i] );
            real_t fyj = half * ( apps_fy2[i] + apps_fy3[i] - apps_fy4[i] - apps_fy1[i] );
            real_t rarea = 1.0f / ( xi * yj - xj * yi + ptiny );
            real_t dfxdx  = rarea * ( fxi * yj - fxj * yi );
            real_t dfydy  = rarea * ( fyj * xi - fyi * xj );
            real_t affine = ( apps_fy1[i] + apps_fy2[i] + apps_fy3[i] + apps_fy4[i] ) /
                            ( apps_y1[i]  + apps_y2[i]  + apps_y3[i]  + apps_y4[i]  );
            apps_div[i] = dfxdx + dfydy + affine;
        }
#endif
        dummy(apps_div, NULL, NULL, NULL, NULL, ptiny);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

