real_t apps_energy(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    real_t rho0 = 1.0f, e_cut = 1.0e-7f, emin = -1.0e15f;
    const real_t inv_rho0 = 1.0f / rho0;

    for (int nl = 0; nl < iterations / 8 + 1; nl++) {
#if defined(__riscv_vector)
        Index_type i = 0;
        for (; i < APPS_N1D; ) {
            size_t vl = __riscv_vsetvl_e32m1((size_t)(APPS_N1D - i));

            vfloat32m1_t v_e_old = __riscv_vle32_v_f32m1(&apps_e_old[i], vl);
            vfloat32m1_t v_delvc = __riscv_vle32_v_f32m1(&apps_delvc[i], vl);
            vfloat32m1_t v_p_old = __riscv_vle32_v_f32m1(&apps_p_old[i], vl);
            vfloat32m1_t v_q_old = __riscv_vle32_v_f32m1(&apps_q_old[i], vl);
            vfloat32m1_t v_work  = __riscv_vle32_v_f32m1(&apps_work[i], vl);

            vfloat32m1_t v_pq   = __riscv_vfadd_vv_f32m1(v_p_old, v_q_old, vl);
            vfloat32m1_t v_term = __riscv_vfmul_vv_f32m1(v_delvc, v_pq, vl);
            vfloat32m1_t v_enew = __riscv_vfsub_vv_f32m1(
                __riscv_vfadd_vv_f32m1(v_e_old, __riscv_vfmul_vf_f32m1(v_work, 0.5f, vl), vl),
                __riscv_vfmul_vf_f32m1(v_term, 0.5f, vl),
                vl);

            __riscv_vse32_v_f32m1(&apps_e_new[i], v_enew, vl);
            i += (Index_type)vl;
        }

        i = 0;
        for (; i < APPS_N1D; ) {
            size_t vl = __riscv_vsetvl_e32m1((size_t)(APPS_N1D - i));

            vfloat32m1_t v_delvc = __riscv_vle32_v_f32m1(&apps_delvc[i], vl);
            vbool32_t m_pos      = __riscv_vmfgt_vf_f32m1_b32(v_delvc, 0.0f, vl);
            vbool32_t m_nonpos   = __riscv_vmnot_m_b32(m_pos, vl);

            vfloat32m1_t v_qnew  = __riscv_vfmv_v_f_f32m1(0.0f, vl);

            if (__riscv_vcpop_m_b32(m_nonpos, vl) != 0) {
                vfloat32m1_t v_comp  = __riscv_vle32_v_f32m1(&apps_compHalfStep[i], vl);
                vfloat32m1_t v_pbvc  = __riscv_vle32_v_f32m1(&apps_pbvc[i], vl);
                vfloat32m1_t v_enew  = __riscv_vle32_v_f32m1(&apps_e_new[i], vl);
                vfloat32m1_t v_bvc   = __riscv_vle32_v_f32m1(&apps_bvc[i], vl);
                vfloat32m1_t v_phalf = __riscv_vle32_v_f32m1(&apps_pHalfStep[i], vl);
                vfloat32m1_t v_qlold = __riscv_vle32_v_f32m1(&apps_ql_old[i], vl);
                vfloat32m1_t v_qqold = __riscv_vle32_v_f32m1(&apps_qq_old[i], vl);

                vfloat32m1_t v_onepc = __riscv_vfadd_vf_f32m1(v_comp, 1.0f, vl);
                vfloat32m1_t v_vhalf = __riscv_vfrdiv_vf_f32m1(v_onepc, 1.0f, vl);
                vfloat32m1_t v_vh2   = __riscv_vfmul_vv_f32m1(v_vhalf, v_vhalf, vl);

                vfloat32m1_t v_t0    = __riscv_vfmul_vv_f32m1(v_pbvc, v_enew, vl);
                vfloat32m1_t v_t1    = __riscv_vfmul_vv_f32m1(v_bvc, v_phalf, vl);
                vfloat32m1_t v_t2    = __riscv_vfmul_vv_f32m1(v_vh2, v_t1, vl);
                vfloat32m1_t v_ssc   = __riscv_vfmul_vf_f32m1(__riscv_vfadd_vv_f32m1(v_t0, v_t2, vl), inv_rho0, vl);

                vbool32_t m_small    = __riscv_vmfle_vf_f32m1_b32(v_ssc, 1.111111e-36f, vl);
                vfloat32m1_t v_sqrt  = __riscv_vfsqrt_v_f32m1(v_ssc, vl);
