                vfloat32m1_t vmul1 = __riscv_vfmul_vv_f32m1(vcoeff, vin1, vl);
                s1 += __riscv_vfmv_f_s_f32m1_f32(
                    __riscv_vfredusum_vs_f32m1_f32m1(
                        vmul1,
                        __riscv_vfmv_v_f_f32m1(0.0f, vl),
                        vl));

                vfloat32m1_t vin2 = __riscv_vle32_v_f32m1(&apps_in[i + 2 + j], vl);
                vfloat32m1_t vmul2 = __riscv_vfmul_vv_f32m1(vcoeff, vin2, vl);
                s2 += __riscv_vfmv_f_s_f32m1_f32(
                    __riscv_vfredusum_vs_f32m1_f32m1(
                        vmul2,
                        __riscv_vfmv_v_f_f32m1(0.0f, vl),
                        vl));

