                vfloat32m1_t vmul3 = __riscv_vfmul_vv_f32m1(vcoeff, vin3, vl);
                s3 += __riscv_vfmv_f_s_f32m1_f32(
                    __riscv_vfredusum_vs_f32m1_f32m1(
                        vmul3,
                        __riscv_vfmv_v_f_f32m1(0.0f, vl),
                        vl));

