                vfloat32m1_t vin = __riscv_vle32_v_f32m1(&apps_in[i + j], vl);
                vfloat32m1_t vmul = __riscv_vfmul_vv_f32m1(vcoeff, vin, vl);
                s += __riscv_vfmv_f_s_f32m1_f32(
                    __riscv_vfredusum_vs_f32m1_f32m1(
                        vmul,
                        __riscv_vfmv_v_f_f32m1(0.0f, vl),
