real_t apps_ltimes_noview(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type num_d = LTIMES_NUM_D, num_m = LTIMES_NUM_M;
    Index_type num_g = LTIMES_NUM_G, num_z = LTIMES_NUM_Z;

    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type z = 0; z < num_z; ++z) {
            const Index_type z_mg_off = z * num_m * num_g;
            const Index_type z_dg_off = z * num_d * num_g;

            for (Index_type g = 0; g < num_g; ++g) {
                const Index_type phi_base = z_mg_off + g * num_m;
                const Index_type psi_base = z_dg_off + g * num_d;

#if defined(__riscv_vector)
                real_t *phi_row = &lt_phidat[phi_base];
                const real_t *psi_col = &lt_psidat[psi_base];

                Index_type m = 0;
                for (; m < num_m; ) {
                    size_t vl = __riscv_vsetvl_e32m4((size_t)(num_m - m));

                    real_t *phi_ptr = phi_row + m;
                    const real_t *ell_ptr = &lt_elldat[m * num_d];

                    vfloat32m4_t vacc = __riscv_vle32_v_f32m4(phi_ptr, vl);

                    Index_type dd = 0;
                    for (; dd + 1 < num_d; dd += 2) {
                        vfloat32m4_t vell0 = __riscv_vlse32_v_f32m4(
                            ell_ptr + dd, (ptrdiff_t)(num_d * sizeof(real_t)), vl);
                        vacc = __riscv_vfmacc_vf_f32m4(vacc, psi_col[dd], vell0, vl);

                        vfloat32m4_t vell1 = __riscv_vlse32_v_f32m4(
                            ell_ptr + dd + 1, (ptrdiff_t)(num_d * sizeof(real_t)), vl);
                        vacc = __riscv_vfmacc_vf_f32m4(vacc, psi_col[dd + 1], vell1, vl);
                    }
                    for (; dd < num_d; ++dd) {
                        vfloat32m4_t vell = __riscv_vlse32_v_f32m4(
                            ell_ptr + dd, (ptrdiff_t)(num_d * sizeof(real_t)), vl);
                        vacc = __riscv_vfmacc_vf_f32m4(vacc, psi_col[dd], vell, vl);
                    }

                    __riscv_vse32_v_f32m4(phi_ptr, vacc, vl);
                    m += (Index_type)vl;
                }
#else
                for (Index_type m = 0; m < num_m; ++m) {
                    real_t sum = lt_phidat[phi_base + m];
                    const Index_type ell_base = m * num_d;
                    for (Index_type dd = 0; dd < num_d; ++dd) {
                        sum += lt_elldat[ell_base + dd] * psi_col[dd];
                    }
                    lt_phidat[phi_base + m] = sum;
                }
#endif
            }
        }
        dummy(lt_phidat, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

